     1	using System.Globalization;
     2	using System.Security.Cryptography;
     3	using System.Text.Json;
     4	namespace JobSearch.Api.Contracts;
     5	public static class EventFingerprint
     6	{
     7	    public const int Version = 1;
     8	    public static string Compute(JobCreatedEvent e)
     9	    {
    10	        var j = e.Job;
    11	        // Transport correlation is diagnostic and is not durable projection identity.
    12	        var bytes = JsonSerializer.SerializeToUtf8Bytes(new object[] { Version, e.EventId.ToString("D"), e.OccurredAt.ToString("O", CultureInfo.InvariantCulture),
    13	            j.Id.ToString("D"), j.CreatedAt.ToString("O", CultureInfo.InvariantCulture), j.Title, j.Department, j.Location, j.Description,
    14	            j.SalaryMin.ToString("F2", CultureInfo.InvariantCulture), j.SalaryMax.ToString("F2", CultureInfo.InvariantCulture), j.ClosingDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture) });
    15	        return Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();
    16	    }
    17	}
