     1	using System.Globalization;
     2	using Microsoft.Extensions.Primitives;
     3	namespace JobSearch.Api.Contracts;
     4	public sealed class QueryReader(TimeProvider clock)
     5	{
     6	    public DateOnly TodayUtc() => DateOnly.FromDateTime(clock.GetUtcNow().UtcDateTime);
     7	    public static bool Available(DateOnly closingDate, DateOnly today) => closingDate > today;
     8	    public static bool TryId(string value, out Guid id) => Guid.TryParseExact(value, "D", out id) && id != Guid.Empty;
     9	    public QueryReadResult Read(IEnumerable<KeyValuePair<string, StringValues>> parameters)
    10	    {
    11	        var values = new Dictionary<string, string>(StringComparer.Ordinal);
    12	        foreach (var p in parameters)
    13	        {
    14	            if (!new[] { "q", "department", "location", "limit", "sort", "cursor" }.Contains(p.Key) || p.Value.Count != 1 || !values.TryAdd(p.Key, p.Value.ToString())) return new(null, "invalid_query");
    15	        }
    16	        try
    17	        {
    18	            var q = Filter(values.GetValueOrDefault("q", ""), 200);
    19	            var department = Filter(values.GetValueOrDefault("department", ""), 100);
    20	            var location = Filter(values.GetValueOrDefault("location", ""), 100);
    21	            var limit = 20;
    22	            if (values.TryGetValue("limit", out var raw) && (!int.TryParse(raw, NumberStyles.None, CultureInfo.InvariantCulture, out limit) || limit is < 1 or > 50)) throw new FormatException();
    23	            var sort = values.GetValueOrDefault("sort", "newest");
    24	            if (sort is not ("newest" or "closing-soon")) throw new FormatException();
    25	            var cursor = values.GetValueOrDefault("cursor");
    26	            if (cursor is not null && (cursor.Length is 0 or > 2048 || cursor.Any(char.IsWhiteSpace) || cursor.Any(char.IsControl))) throw new FormatException();
    27	            return new(new(q, department, location, limit, sort, cursor), null);
    28	        }
    29	        catch (FormatException) { return new(null, "invalid_query"); }
    30	    }
    31	    private static string? Filter(string value, int maximum)
    32	    {
    33	        var trimmed = value.Trim();
    34	        if (trimmed.Length > maximum || trimmed.Any(char.IsControl)) throw new FormatException();
    35	        return trimmed.Length == 0 ? null : trimmed;
    36	    }
    37	}
