     5	namespace JobSearch.Api.Diagnostics;
     6	public interface IDatabaseProbe { Task<bool> ReadyAsync(CancellationToken token); }
     7	public sealed class SearchDatabaseProbe(IDbContextFactory<SearchDbContext> factory):IDatabaseProbe
     8	{
     9	    public async Task<bool> ReadyAsync(CancellationToken token)
    10	    {
    11	        await using var db=await factory.CreateDbContextAsync(token);
    12	        var applied=await db.Database.SqlQueryRaw<string>("SELECT \"MigrationId\" AS \"Value\" FROM \"__EFMigrationsHistory\" ORDER BY \"MigrationId\"").ToArrayAsync(token);
    13	        if(!db.Database.GetMigrations().Order().SequenceEqual(applied))return false;
    14	        await db.Jobs.AsNoTracking().Select(x=>x.Id).Take(1).ToArrayAsync(token);
    15	        return true;
    16	    }
    17	}
    18	[ApiController]
    19	[Route("health")]
    20	public sealed class HealthController(IDatabaseProbe database,IngestionState ingestion,TimeProvider clock,ILogger<HealthController> logger):ControllerBase
    21	{
    22	    [HttpGet("live")]
    23	    public IActionResult Live()=>Ok(new {status="live"});
    24	    [HttpGet("ingestion")]
    25	    public IActionResult Ingestion()=>StatusCode(ingestion.Current==ConsumerState.Running?200:503,new {status=ingestion.Current.ToString()});
    26	    [HttpGet("ready")]
    27	    public async Task<IActionResult> Ready(CancellationToken token)
    28	    {
    29	        if(ingestion.Current is ConsumerState.Draining or ConsumerState.Stopped)return StatusCode(503);
    30	        using var budget=new CancellationTokenSource(TimeSpan.FromSeconds(3),clock);
    31	        using var linked=CancellationTokenSource.CreateLinkedTokenSource(token,budget.Token);
    32	        try { return StatusCode(await database.ReadyAsync(linked.Token).WaitAsync(linked.Token)?200:503); }
    33	        catch(Exception ex) { logger.LogWarning(new EventId(4301,"ReadUnavailable"),"Read readiness unavailable; failure {Failure}",ex.GetType().Name);return StatusCode(503); }
    34	    }
    35	}
