     1	using System.Diagnostics;
     2	using Microsoft.AspNetCore.Routing;
     3	
     4	namespace JobSearch.Api.Diagnostics;
     5	
     6	public sealed class RequestDiagnosticsMiddleware(RequestDelegate next, ILogger<RequestDiagnosticsMiddleware> logger)
     7	{
     8	    public const string TraceHeader = "X-Trace-Id";
     9	
    10	    public async Task InvokeAsync(HttpContext context)
    11	    {
    12	        context.TraceIdentifier = Activity.Current?.TraceId.ToString() ?? context.TraceIdentifier;
    13	        var traceId = context.TraceIdentifier;
    14	        context.Response.OnStarting(() =>
    15	        {
    16	            context.Response.Headers[TraceHeader] = traceId;
    17	            return Task.CompletedTask;
    18	        });
    19	
    20	        using var scope = logger.BeginScope(new Dictionary<string, object> { ["TraceId"] = traceId });
    21	        var started = Stopwatch.GetTimestamp();
    22	
    23	        try
    24	        {
    25	            await next(context);
    26	        }
    27	        finally
    28	        {
    29	            // Use the route template, never arbitrary URLs, query strings, headers or bodies.
    30	            var route = (context.GetEndpoint() as RouteEndpoint)?.RoutePattern.RawText ?? "unmatched";
    31	            SearchMetrics.Request(context.Response.StatusCode,Stopwatch.GetElapsedTime(started).TotalMilliseconds);
    32	            logger.LogInformation(new EventId(1000, "RequestCompleted"),
    33	                "HTTP {Method} {Route} completed with {StatusCode} in {ElapsedMilliseconds} ms; trace {TraceId}",
    34	                context.Request.Method, route, context.Response.StatusCode,
    35	                Stopwatch.GetElapsedTime(started).TotalMilliseconds, traceId);
    36	        }
    37	    }
    38	}
