     2	using JobSearch.Api.Messaging;
     3	namespace JobSearch.Api.Diagnostics;
     4	public static class SearchMetrics
     5	{
     6	    public const string MeterName="JobSearch.Api";
     7	    private static readonly Meter Meter=new(MeterName,"1.0");
     8	    private static readonly Counter<long> Projections=Meter.CreateCounter<long>("search.projections");
     9	    private static readonly Counter<long> Redeliveries=Meter.CreateCounter<long>("search.redeliveries");
    10	    private static readonly Counter<long> Quarantines=Meter.CreateCounter<long>("search.quarantines");
    11	    private static readonly Counter<long> Connections=Meter.CreateCounter<long>("search.consumer.transitions");
    12	    private static readonly Histogram<double> Requests=Meter.CreateHistogram<double>("search.request.duration","ms");
    13	    public static void Projection(DeliveryOutcome outcome)=>Projections.Add(1,new KeyValuePair<string,object?>("outcome",outcome.ToString()));
    14	    public static void Redelivery()=>Redeliveries.Add(1);
