     8	    {
     9	        if(!options.Value.Enabled){state.Set(ConsumerState.Disabled);return;}
    10	        var attempt=0;
    11	        try
    12	        {
    13	            while(!token.IsCancellationRequested)
    14	            {
    15	                state.Set(ConsumerState.Connecting);
    16	                var started=clock.GetTimestamp();
    17	                try { await session.RunAsync(token);attempt=0; }
    18	                catch(OperationCanceledException) when(token.IsCancellationRequested){return;}
    19	                catch(Exception ex)
    20	                {
    21	                    if(clock.GetElapsedTime(started)>=TimeSpan.FromSeconds(30))attempt=0;
    22	                    logger.LogWarning(new EventId(4100,"ConsumerSessionFailed"),"Consumer session ended; classification {Classification}; failure {Failure}",ConsumerFailures.Classify(ex),ex.GetType().Name);
    23	                }
    24	                state.Set(ConsumerState.Backoff);
    25	                var delay=ConsumerFailures.Delay(attempt,options.Value,jitter.Next());attempt=Math.Min(30,attempt+1);
    26	                try { await Task.Delay(delay,clock,token); }
    27	                catch(OperationCanceledException){return;}
    28	            }
    29	        }
