    18	        {
    19	            var existing=await ReadIdentitiesAsync(row,token);
    20	            if(existing.Count==0) throw;
    21	            return Classify(existing,row);
    22	        }
    23	        catch (ProjectionCommitUncertainException)
    24	        {
    25	            // Fresh durable read; failed/missing/conflicting read cannot authorize ACK.
    26	            var existing=await ReadIdentitiesAsync(row,token);
