    37	    {
    38	        await using var context=await contexts.CreateDbContextAsync(token);
    39	        await using var transaction=await context.Database.BeginTransactionAsync(token);
    40	        await context.LockIngestionAsync(token);
    41	        var existing=await context.FindIdentitiesAsync(row.Id,row.EventId,token);
